import type { Difficulty, Food } from "./types";

/**
 * EXPANSION PACK — real dishes for major culinary nations, deepening the
 * "foods >> countries" ratio. Same schema as seed data; merged with
 * de-duplication in the store. Add more packs here as the database grows.
 */

let n = 0;
function E(
  en: string, fa: string, ar: string, countryId: string, difficulty: Difficulty, emoji: string,
  spice: 0 | 1 | 2 | 3, meat: string[], veg: boolean, vegan: boolean,
  categories: string[], ingredients: string[], desc: string, fact?: string
): Food {
  n += 1;
  return {
    id: `xp_${String(n).padStart(3, "0")}`,
    name: { en, fa, ar },
    countryId,
    categories,
    ingredients,
    meat,
    veg,
    vegan,
    spice,
    difficulty,
    emoji,
    desc: { en: desc },
    fact: fact ? { en: fact } : undefined,
  };
}

